410: int CheckKeyCodes(const char* k, MMKeyCode *key)
411: {
412: 	if (!key) return -1;
413: 
414: 	if (strlen(k) == 1)
415: 	{
416: 		*key = keyCodeForChar(*k);
417: 		return 0;
418: 	}
419: 
420: 	*key = K_NOT_A_KEY;
421: 
422: 	KeyNames* kn = key_names;
423: 	while (kn->name)
424: 	{
425: 		if (strcmp(k, kn->name) == 0)
426: 		{
427: 			*key = kn->key;
428: 			break;
429: 		}
430: 		kn++;
431: 	}
432: 
433: 	if (*key == K_NOT_A_KEY)
434: 	{
435: 		return -2;
436: 	}
437: 
438: 	return 0;
439: }
