441: int CheckKeyFlags(const char* f, MMKeyFlags* flags)
442: {
443: 	if (!flags) return -1;
444: 
445: 	if (strcmp(f, "alt") == 0 || strcmp(f, "right_alt") == 0)
446: 	{
447: 		*flags = MOD_ALT;
448: 	}
449: 	else if(strcmp(f, "command") == 0)
450: 	{
451: 		*flags = MOD_META;
452: 	}
453: 	else if(strcmp(f, "control") == 0 || strcmp(f, "right_control") == 0 || strcmp(f, "left_control") == 0)
454: 	{
455: 		*flags = MOD_CONTROL;
456: 	}
457: 	else if(strcmp(f, "shift") == 0 || strcmp(f, "right_shift") == 0)
458: 	{
459: 		*flags = MOD_SHIFT;
460: 	}
461: 	else if(strcmp(f, "none") == 0)
462: 	{
463: 		*flags = MOD_NONE;
464: 	}
465: 	else
466: 	{
467: 		return -2;
468: 	}
469: 
470: 	return 0;
471: }
