522: 					break;
523: 				case -2:
524: 					Napi::Error::New(env, "Invalid key flag specified.").ThrowAsJavaScriptException();
525: return env.Null();
526: 					break;
527: 			}
528: 			break;
529: 		case 1:
530: 			break;
531: 		default:
532: 			Napi::Error::New(env, "Invalid number of arguments.").ThrowAsJavaScriptException();
533: return env.Null();
534: 	}
535: 
536: 	switch(CheckKeyCodes(k, &key))
537: 	{
538: 		case -1:
539: 			Napi::Error::New(env, "Null pointer in key code.").ThrowAsJavaScriptException();
540: return env.Null();
541: 			break;
