588: 					break;
589: 			}
590: 			break;
591: 		case 2:
592: 			break;
593: 		default:
594: 			Napi::Error::New(env, "Invalid number of arguments.").ThrowAsJavaScriptException();
595: return env.Null();
596: 	}
597: 
598: 	//Get down value if provided.
599: 	if (info.Length() > 1)
600: 	{
601: 		const char *d;
602: 
603: 		std::string dstr = info[1].As<Napi::String>();
604: 		d = dstr.c_str();
