606: 		if (strcmp(d, "down") == 0)
607: 		{
608: 			down = true;
609: 		}
610: 		else if (strcmp(d, "up") == 0)
611: 		{
612: 			down = false;
613: 		}
614: 		else
615: 		{
616: 			Napi::Error::New(env, "Invalid key state specified.").ThrowAsJavaScriptException();
617: return env.Null();
618: 		}
619: 	}
620: 
621: 	//Get the actual key.
622: 	switch(CheckKeyCodes(k, &key))
623: 	{
624: 		case -1:
625: 			Napi::Error::New(env, "Null pointer in key code.").ThrowAsJavaScriptException();
626: return env.Null();
627: 			break;
628: 		case -2:
629: 			Napi::Error::New(env, "Invalid key code specified.").ThrowAsJavaScriptException();
630: return env.Null();
631: 			break;
632: 		default:
633: 			toggleKeyCode(key, down, flags);
634: 			microsleep(keyboardDelay);
635: 	}
636: 
637: 	return Napi::Number::New(env, 1);
