726: /**
727:  * Pad hex color code with leading zeros.
728:  * @param color Hex value to pad.
729:  * @param hex   Hex value to output.
730:  */
731: void padHex(MMRGBHex color, char* hex)
732: {
733: 	//Length needs to be 7 because snprintf includes a terminating null.
734: 	//Use %06x to pad hex value with leading 0s.
735: 	snprintf(hex, 7, "%06x", color);
736: }
