744: 		Napi::Error::New(env, "Invalid number of arguments.").ThrowAsJavaScriptException();
745: return env.Null();
746: 	}
747: 
748: 	MMBitmapRef bitmap;
749: 	MMRGBHex color;
750: 
751: 	double x = info[0].ToNumber().DoubleValue();
752: 	double y = info[1].ToNumber().DoubleValue();
753: 
754: 	if (x < 0 || y < 0 ||
755: 	    !pointVisibleOnMainDisplay(MMPointMake(static_cast<size_t>(x), static_cast<size_t>(y))))
756: 	{
757: 		Napi::Error::New(env, "Requested coordinates are outside the main screen's dimensions.").ThrowAsJavaScriptException();
758: return env.Null();
759: 	}
760: 
761: 	bitmap = copyMMBitmapFromDisplayInRect(MMRectMake(static_cast<size_t>(x), static_cast<size_t>(y), 1, 1));
762: 	if (bitmap == NULL) {
763: 		Napi::Error::New(env, "Failed to capture the requested pixel.")
764: 			.ThrowAsJavaScriptException();
765: 		return env.Null();
766: 	}
767: 
768: 	color = MMRGBHexAtPoint(bitmap, 0, 0);
769: 
770: 	char hex[7];
771: 
772: 	padHex(color, hex);
773: 
774: 	destroyMMBitmap(bitmap);
775: 
776: 	return Napi::String::New(env, hex);
777: }
