889: //Convert object from Javascript to a C++ class (BMP).
890: BMP buildBMP(Napi::Object obj)
891: {
892: 	BMP img;
893: 
894: 	img.width = obj.Get("width").As<Napi::Number>().Uint32Value();
895: 	img.height = obj.Get("height").As<Napi::Number>().Uint32Value();
896: 	img.byteWidth = obj.Get("byteWidth").As<Napi::Number>().Uint32Value();
897: 	img.bitsPerPixel = obj.Get("bitsPerPixel").As<Napi::Number>().Uint32Value();
898: 	img.bytesPerPixel = obj.Get("bytesPerPixel").As<Napi::Number>().Uint32Value();
899: 
900: 	char* buf = obj.Get("image").As<Napi::Buffer<char>>().Data();
901: 
902: 	//Convert the buffer to a uint8_t which createMMBitmap requires.
903: 	img.image = (uint8_t *)malloc(img.byteWidth * img.height);
904: 	memcpy(img.image, buf, img.byteWidth * img.height);
905: 
906: 	return img;
907:  }
