252: uint8_t *createBitmapData(MMBitmapRef bitmap, size_t *len)
253: {
254: 	/* BMP files are always aligned to 4 bytes. */
255: 	const size_t bytewidth = ((bitmap->width * bitmap->bytesPerPixel) + 3) & ~3;
256: 
257: 	const size_t imageSize = bytewidth * bitmap->height;
258: 	struct BITMAP_FILE_HEADER *fileHeader;
259: 	struct BITMAP_INFO_HEADER *dibHeader;
260: 
261: 	/* Should always be 54. */
262: 	const size_t imageOffset = sizeof(*fileHeader) + sizeof(*dibHeader);
263: 	uint8_t *data;
264: 	const size_t dataLen = imageOffset + imageSize;
265: 
266: 	data = calloc(1, dataLen);
267: 	if (data == NULL) return NULL;
268: 
269: 	/* Save top header. */
270: 	fileHeader = (struct BITMAP_FILE_HEADER *)data;
271: 	fileHeader->magic = BMP_MAGIC;
272: 	fileHeader->fileSize = (uint32_t)(sizeof(*dibHeader) + imageSize);
273: 	fileHeader->imageOffset = (uint32_t)imageOffset;
274: 
275: 	/* BMP files are always stored as little-endian, so we need to convert back
276: 	 * if necessary. */
277: 	convertBitmapFileHeader(fileHeader);
278: 
279: 	/* Copy Windows v3 header. */
280: 	dibHeader = (struct BITMAP_INFO_HEADER *)(data + sizeof(*fileHeader));
281: 	dibHeader->headerSize = sizeof(*dibHeader); /* Should always be 40. */
282: 	dibHeader->width = (int32_t)bitmap->width;
283: 	dibHeader->height = -(int32_t)bitmap->height; /* Our bitmaps are "flipped". */
284: 	dibHeader->colorPlanes = 1;
285: 	dibHeader->bitsPerPixel = bitmap->bitsPerPixel;
286: 	dibHeader->compression = kBMP_RGB; /* Don't save with compression. */
287: 	dibHeader->imageSize = (uint32_t)imageSize;
288: 
289: 	convertBitmapInfoHeader(dibHeader);
290: 
291: 	/* Lastly, copy the pixel data. */
292: 	copyBGRDataFromMMBitmap(bitmap, data + imageOffset);
293: 
294: 	if (len != NULL) *len = dataLen;
295: 	return data;
