322: static uint8_t *readImageData(FILE *fp, size_t width, size_t height,
323:                               uint8_t bytesPerPixel, size_t bytewidth)
324: {
325: 	size_t imageSize = bytewidth * height;
326: 	uint8_t *imageBuf = calloc(1, imageSize);
327: 
328: 	if (MMRGB_IS_BGR && (bytewidth % 4) == 0) { /* No conversion needed. */
329: 		if (fread(imageBuf, imageSize, 1, fp) == 0) {
330: 			free(imageBuf);
331: 			return NULL;
332: 		}
333: 	} else { /* Convert from BGR with 4-byte alignment. */
334: 		uint8_t *row = malloc(bytewidth);
335: 		size_t y;
336: 		const size_t bmp_bytewidth = (width * bytesPerPixel + 3) & ~3;
337: 
338: 		if (row == NULL) return NULL;
339: 		assert(bmp_bytewidth <= bytewidth);
340: 
341: 		/* Read image data row by row. */
342: 		for (y = 0; y < height; ++y) {
343: 			const size_t rowOffset = y * bytewidth;
344: 			size_t x;
345: 			uint8_t *rowptr = row;
346: 			if (fread(row, bmp_bytewidth, 1, fp) == 0) {
347: 				free(imageBuf);
348: 				free(row);
349: 				return NULL;
350: 			}
351: 
352: 			for (x = 0; x < width; ++x) {
353: 				const size_t colOffset = x * bytesPerPixel;
354: 				MMRGBColor *color = (MMRGBColor *)(imageBuf +
355: 				                                   rowOffset + colOffset);
356: 
357: 				/* BMP files are stored in BGR format. */
358: 				color->blue = rowptr[0];
359: 				color->green = rowptr[1];
360: 				color->red = rowptr[2];
361: 				rowptr += bytesPerPixel;
362: 			}
363: 		}
364: 
365: 		free(row);
366: 	}
367: 
368: 	return imageBuf;
369: }
