371: static void copyBGRDataFromMMBitmap(MMBitmapRef bitmap, uint8_t *dest)
372: {
373: 	if (MMRGB_IS_BGR && (bitmap->bytewidth % 4) == 0) { /* No conversion needed. */
374: 		memcpy(dest, bitmap->imageBuffer, bitmap->bytewidth * bitmap->height);
375: 	} else { /* Convert to RGB with other-than-4-byte alignment. */
376: 		const size_t bytewidth = (bitmap->width * bitmap->bytesPerPixel + 3) & ~3;
377: 		size_t y;
378: 
379: 		/* Copy image data row by row. */
380: 		for (y = 0; y < bitmap->height; ++y) {
381: 			uint8_t *rowptr = dest + (y * bytewidth);
382: 			size_t x;
383: 			for (x = 0; x < bitmap->width; ++x) {
384: 				MMRGBColor *color = MMRGBColorRefAtPoint(bitmap, x, y);
385: 
386: 				/* BMP files are stored in BGR format. */
387: 				rowptr[0] = color->blue;
388: 				rowptr[1] = color->green;
389: 				rowptr[2] = color->red;
390: 
391: 				rowptr += bitmap->bytesPerPixel;
392: 			}
393: 		}
394: 	}
395: }
