397: /* Perform an in-place swap from Quadrant 1 to Quadrant III format (upside-down
398:  * PostScript/GL to right side up QD/CG raster format) We do this in-place,
399:  * which requires more copying, but will touch only half the pages.
400:  *
401:  * This is blatantly copied from Apple's glGrab example code. */
402: void flipBitmapData(void *data, size_t width, size_t height, size_t bytewidth)
403: {
404: 	size_t top, bottom;
405: 	void *topP;
406: 	void *bottomP;
407: 	void *tempbuf;
408: 
409: 	if (height <= 1) return; /* No flipping necessary if height is <= 1. */
410: 
411: 	top = 0;
412: 	bottom = height - 1;
413: 	tempbuf = malloc(bytewidth);
414: 	if (tempbuf == NULL) return;
415: 
416: 	while (top < bottom) {
417: 		topP = (void *)((top * bytewidth) + (intptr_t)data);
418: 		bottomP = (void *)((bottom * bytewidth) + (intptr_t)data);
419: 
420: 		/* Save and swap scanlines.
421: 		 * Does a simple in-place exchange with a temp buffer. */
422: 		memcpy(tempbuf, topP, bytewidth);
423: 		memcpy(topP, bottomP, bytewidth);
424: 		memcpy(bottomP, tempbuf, bytewidth);
425: 
426: 		++top;
427: 		--bottom;
428: 	}
429: 	free(tempbuf);
430: }

